#pragma once
#ifndef WIN32_LEAN_AND_MEAN
#define WIN32_LEAN_AND_MEAN
#endif
#include <windows.h>

#include <cstdint>
#include <filesystem>
#include <string>
#include <string_view>

#include "kiln_api.h"
#include "kiln_version.h"  // generated by CMake from the repository's VERSION file

namespace kiln {

inline constexpr std::string_view kVersion = KILN_VERSION;

std::string to_utf8(std::wstring_view w);
std::wstring to_wide(std::string_view s);

struct Paths {
    std::filesystem::path exe;      // full path of the game executable
    std::filesystem::path game;     // its directory
    std::filesystem::path kiln;     // <game>/kiln
    std::filesystem::path logs;     // <game>/kiln/logs
    std::filesystem::path mods;     // <game>/kiln/mods
    std::filesystem::path data;     // <game>/kiln/data
    std::filesystem::path control;  // <game>/kiln/control
    std::filesystem::path plugins;  // <game>/kiln/plugins
    std::filesystem::path sigdb;    // <game>/kiln/sigdb
    std::filesystem::path config;   // KILN_PATH_CONFIG: the profile's configDir, else <game>/kiln/config
    std::filesystem::path state;    // <game>/kiln/state (KILN_PATH_STATE): files for the launcher
};
const Paths& paths();
void init_paths();
void set_config_dir(const std::filesystem::path& dir);  // profile.cpp, once, during boot

// Writes `text` to `file` atomically (<file>.tmp, then a replacing rename); creates the folder. False on failure.
bool write_file_atomic(const std::filesystem::path& file, std::string_view text);
// The whole file as bytes (UTF-8 text); false when it cannot be read.
bool read_file(const std::filesystem::path& file, std::string* out);
// JSON with comments (// and /* */) and trailing commas -> plain JSON (strings untouched; line numbers kept).
std::string jsonc_to_json(std::string_view text);
// Now, as RFC 3339 UTC with seconds ("2026-11-04T12:00:00Z").
std::string utc_now();
// A path as text in Windows form (UTF-8), as written to kiln.log and the state files.
inline std::string u8(const std::filesystem::path& p) { return to_utf8(p.wstring()); }

// What the proxy passed to kiln_boot, normalized: fields a v1 proxy did not send read as zero / empty.
const KilnBootInfo& boot_info();

double now_ms();  // QPC milliseconds

inline KilnStr kstr(std::string_view s) { return KilnStr{s.data(), s.size()}; }
inline std::string_view sv(KilnStr s) { return s.ptr ? std::string_view(s.ptr, s.len) : std::string_view(); }

}  // namespace kiln
